import { readFileSync, realpathSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const TYPES = new Set(['started', 'succeeded', 'failed']);

function fail(message) {
  throw new Error(message);
}

function parseEvent(line, lineNumber) {
  let event;
  try {
    event = JSON.parse(line);
  } catch {
    fail(`line ${lineNumber}: invalid JSON`);
  }
  if (typeof event !== 'object' || event === null || Array.isArray(event)) {
    fail(`line ${lineNumber}: each event must be a non-null, non-array object`);
  }
  const { id, job, attempt, seq, type } = event;
  if (typeof id !== 'string' || id.length === 0) {
    fail(`line ${lineNumber}: "id" must be a nonempty string`);
  }
  if (typeof job !== 'string' || job.length === 0) {
    fail(`line ${lineNumber}: "job" must be a nonempty string`);
  }
  if (!Number.isSafeInteger(attempt) || attempt < 1) {
    fail(`line ${lineNumber}: "attempt" must be a positive safe integer`);
  }
  if (!Number.isSafeInteger(seq) || seq < 0) {
    fail(`line ${lineNumber}: "seq" must be a nonnegative safe integer`);
  }
  if (typeof type !== 'string' || !TYPES.has(type)) {
    fail(`line ${lineNumber}: "type" must be "started", "succeeded", or "failed"`);
  }
  return { id, job, attempt, seq, type };
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    fail('input must be a JSONL string');
  }

  // Deduplicate by id before reducing; extra fields are ignored, including
  // for the duplicate comparison (only the five required fields are kept).
  const byId = new Map();
  let duplicates = 0;
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '') continue; // whitespace-only lines, CRLF remnants
    const event = parseEvent(line, i + 1);
    const existing = byId.get(event.id);
    if (existing) {
      if (
        existing.job === event.job &&
        existing.attempt === event.attempt &&
        existing.seq === event.seq &&
        existing.type === event.type
      ) {
        duplicates += 1; // every extra identical copy counts
      } else {
        fail(`id ${JSON.stringify(event.id)} conflicts with an earlier event`);
      }
    } else {
      byId.set(event.id, event);
    }
  }

  // Group unique events by (job, attempt).
  const byJob = new Map();
  for (const event of byId.values()) {
    let attempts = byJob.get(event.job);
    if (!attempts) {
      attempts = new Map();
      byJob.set(event.job, attempts);
    }
    let slot = attempts.get(event.attempt);
    if (!slot) {
      slot = { started: null, terminal: null };
      attempts.set(event.attempt, slot);
    }
    if (event.type === 'started') {
      if (slot.started) {
        fail(
          `job ${JSON.stringify(event.job)} attempt ${event.attempt} has more than one started event`
        );
      }
      slot.started = event;
    } else if (slot.terminal) {
      fail(
        `job ${JSON.stringify(event.job)} attempt ${event.attempt} has more than one terminal event`
      );
    } else {
      slot.terminal = event;
    }
  }

  const jobs = [];
  for (const [job, attempts] of byJob) {
    const attemptRecords = [];
    for (const [attempt, slot] of attempts) {
      if (!slot.started) {
        fail(
          `job ${JSON.stringify(job)} attempt ${attempt} has a terminal event without a started event`
        );
      }
      let status = 'running';
      let finishedSeq = null;
      if (slot.terminal) {
        if (slot.terminal.seq <= slot.started.seq) {
          fail(
            `job ${JSON.stringify(job)} attempt ${attempt}: terminal seq ${slot.terminal.seq} must be strictly greater than start seq ${slot.started.seq}`
          );
        }
        status = slot.terminal.type;
        finishedSeq = slot.terminal.seq;
      }
      attemptRecords.push({ attempt, status, startedSeq: slot.started.seq, finishedSeq });
    }
    attemptRecords.sort((a, b) => a.attempt - b.attempt);
    jobs.push({ job, attempts: attemptRecords });
  }
  // Plain < / > on strings compares UTF-16 code units (no locale collation).
  jobs.sort((a, b) => (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));

  return { jobs, duplicates };
}

function runCli() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node receipt-report.js <logfile> (expected exactly one argument)\n');
    process.exitCode = 2;
    return;
  }
  const [file] = args;
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch (error) {
    process.stderr.write(`cannot read ${JSON.stringify(file)}: ${error.message}\n`);
    process.exitCode = 2;
    return;
  }
  let report;
  try {
    report = reduceEvents(text);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
    return;
  }
  process.stdout.write(`${JSON.stringify(report)}\n`);
  process.exitCode = 0;
}

// Only run the CLI when this file itself is the main module, so that
// importing reduceEvents has no side effects.
function isCliEntry() {
  if (process.argv[1] === undefined) return false;
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isCliEntry()) {
  runCli();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { reduceEvents } from '../receipt-report.js';

const jsonl = (events) => events.map((event) => JSON.stringify(event)).join('\n');
const start = (id, job, attempt, seq) => ({ id, job, attempt, seq, type: 'started' });
const term = (id, job, attempt, seq, type) => ({ id, job, attempt, seq, type });

test('empty / whitespace-only input (CRLF and missing final newline allowed)', () => {
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents('   \n\t\r\n\r \n'), { jobs: [], duplicates: 0 });
  assert.deepEqual(
    reduceEvents(jsonl([start('a', 'x', 1, 0)])),
    reduceEvents(jsonl([start('a', 'x', 1, 0)]) + '\n')
  );
});

test('terminal arriving before start, plus running attempt', () => {
  assert.deepEqual(
    reduceEvents(jsonl([
      term('t', 'build', 1, 7, 'failed'),
      start('s', 'build', 1, 3),
      start('r', 'build', 5, 10),
    ])),
    {
      jobs: [{ job: 'build', attempts: [
        { attempt: 1, status: 'failed', startedSeq: 3, finishedSeq: 7 },
        { attempt: 5, status: 'running', startedSeq: 10, finishedSeq: null },
      ] }],
      duplicates: 0,
    }
  );
});

test('duplicates: extra identical copies counted, differing extra fields ignored', () => {
  const e = { id: 's', job: 'x', attempt: 1, seq: 0, type: 'started' };
  const two = reduceEvents(jsonl([e, { ...e, metadata: 'a' }, { ...e, other: 1 }]));
  assert.equal(two.duplicates, 2);
  assert.equal(two.jobs[0].attempts[0].status, 'running');
});

test('conflicting duplicate required field -> error', () => {
  const base = { id: 's', job: 'x', attempt: 1, seq: 0, type: 'started' };
  for (const diff of [
    { id: 's2' },
    { job: 'y' },
    { attempt: 2 },
    { seq: 1 },
    { type: 'failed' },
  ]) {
    assert.throws(
      () => reduceEvents(jsonl([base, { ...base, ...diff }])),
      Error,
      JSON.stringify(diff)
    );
  }
});

test('attempts independent: overlapping ranges, gaps allowed', () => {
  const out = reduceEvents(jsonl([
    start('a1', 'j', 1, 0),
    term('a1t', 'j', 1, 9, 'succeeded'),
    start('a3', 'j', 3, 4),
    term('a3t', 'j', 3, 8, 'failed'),
    start('a7', 'j', 7, 5),
  ]));
  assert.deepEqual(out, {
    jobs: [{ job: 'j', attempts: [
      { attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 9 },
      { attempt: 3, status: 'failed', startedSeq: 4, finishedSeq: 8 },
      { attempt: 7, status: 'running', startedSeq: 5, finishedSeq: null },
    ] }],
    duplicates: 0,
  });
});

test('jobs sorted by UTF-16 code units, not locale', () => {
  const out = reduceEvents(jsonl([
    start('a', 'über', 1, 0),
    start('b', 'ÜB', 1, 0),
    start('c', 'zz', 1, 0),
    start('d', 'a b', 1, 0),
  ]));
  assert.deepEqual(out.jobs.map((j) => j.job), ['ÜB', 'a b', 'zz', 'über']);
});

test('special id/job strings: __proto__, whitespace, unicode', () => {
  const events = [
    start('__proto__', '__proto__', 1, 0),
    term('t', '__proto__', 1, 2, 'succeeded'),
    start('  spaced  ', '  a  ', 1, 0),
  ];
  const out = reduceEvents(jsonl(events));
  assert.deepEqual(out.jobs[0].job, '__proto__');
  assert.deepEqual(out.jobs[1].job, '  a  ');
  assert.deepEqual(out.jobs[1].attempts[0].startedSeq, 0);
  assert.equal(out.duplicates, 0);
  assert.equal(Object.prototype.x, undefined); // no proto pollution
});

test('shared seq across different events is fine; terminal seq equal to start is not', () => {
  assert.deepEqual(
    reduceEvents(jsonl([
      start('s', 'j', 1, 5),
      term('t', 'j', 2, 5, 'succeeded'),
      start('s2', 'j', 2, 4),
    ])),
    {
      jobs: [{ job: 'j', attempts: [
        { attempt: 1, status: 'running', startedSeq: 5, finishedSeq: null },
        { attempt: 2, status: 'succeeded', startedSeq: 4, finishedSeq: 5 },
      ] }],
      duplicates: 0,
    }
  );
  assert.throws(() => reduceEvents(jsonl([
    start('s', 'j', 1, 5),
    term('t', 'j', 1, 5, 'succeeded'),
  ])));
  assert.throws(() => reduceEvents(jsonl([
    start('s', 'j', 1, 5),
    term('t', 'j', 1, 4, 'succeeded'),
  ])));
});

test('structural errors', () => {
  // orphan terminal
  assert.throws(() => reduceEvents(jsonl([term('t', 'x', 1, 5, 'failed')])));
  // repeated start
  assert.throws(() => reduceEvents(jsonl([
    start('s1', 'x', 1, 0), start('s2', 'x', 1, 1),
  ])));
  // repeated terminal
  assert.throws(() => reduceEvents(jsonl([
    start('s1', 'x', 1, 0), term('t1', 'x', 1, 2, 'succeeded'), term('t2', 'x', 1, 3, 'failed'),
  ])));
  // same id reused for start and terminal of one attempt (conflict)
  assert.throws(() => reduceEvents(jsonl([
    start('s1', 'x', 1, 0), term('s1', 'x', 1, 2, 'succeeded'),
  ])));
});

test('invalid required fields are rejected (no coercion)', () => {
  const base = { id: 'i', job: 'j', attempt: 1, seq: 0, type: 'started' };
  const bad = [
    'not json',
    '"string"',
    '42',
    'true',
    'null',
    '[1,2]',
    '{',
    JSON.stringify({ ...base, id: '' }),
    JSON.stringify({ ...base, id: 1 }),
    JSON.stringify({ ...base, id: '  '.replace(' ', '\t') && null }),
    JSON.stringify({ ...base, job: '' }),
    JSON.stringify({ ...base, job: 2 }),
    JSON.stringify({ ...base, attempt: 0 }),
    JSON.stringify({ ...base, attempt: -1 }),
    JSON.stringify({ ...base, attempt: 1.5 }),
    JSON.stringify({ ...base, attempt: '1' }),
    JSON.stringify({ ...base, attempt: true }),
    JSON.stringify({ ...base, attempt: 2 ** 53 }),
    JSON.stringify({ ...base, seq: -1 }),
    JSON.stringify({ ...base, seq: 1.5 }),
    JSON.stringify({ ...base, seq: '0' }),
    JSON.stringify({ ...base, seq: null }),
    JSON.stringify({ ...base, type: 'STARTED' }),
    JSON.stringify({ ...base, type: 'done' }),
    JSON.stringify({ ...base, type: 5 }),
    JSON.stringify({ ...base, type: null }),
  ];
  for (const line of bad) {
    assert.throws(() => reduceEvents(line), Error, JSON.stringify(line));
  }
});

test('extra fields are ignored', () => {
  const out = reduceEvents(jsonl([
    { id: 's', job: 'x', attempt: 1, seq: 0, type: 'started', meta: 1 },
    { id: 't', job: 'x', attempt: 1, seq: 9, type: 'succeeded', extra: { nested: true } },
  ]));
  assert.deepEqual(out, {
    jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 9 }] }],
    duplicates: 0,
  });
});

test('importing the module does not run the CLI', () => {
  const result = spawnSync(process.execPath, ['-e', `
    import(${JSON.stringify(new URL('../receipt-report.js', import.meta.url).href)});
    if (process.stdout.writableLength) process.exit(3);
  `], { encoding: 'utf8' });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, '');
});

test('CLI end-to-end', () => {
  const dir = mkdtempSync(join(tmpdir(), 'receipt-'));
  const okFile = join(dir, 'ok.jsonl');
  writeFileSync(okFile, jsonl([
    start('s', 'build', 1, 2),
    term('t', 'build', 1, 9, 'succeeded'),
    start('r', 'build', 2, 8),
  ]), 'utf8');
  const badFile = join(dir, 'bad.jsonl');
  writeFileSync(badFile, '{bad\n', 'utf8');
  const missing = join(dir, 'nope.jsonl');

  try {
    let r = spawnSync(process.execPath, ['receipt-report.js', okFile], {
      cwd: new URL('..', import.meta.url).pathname,
      encoding: 'utf8',
    });
    assert.equal(r.status, 0, r.stderr);
    assert.equal(r.stdout, JSON.stringify({
      jobs: [{ job: 'build', attempts: [
        { attempt: 1, status: 'succeeded', startedSeq: 2, finishedSeq: 9 },
        { attempt: 2, status: 'running', startedSeq: 8, finishedSeq: null },
      ] }],
      duplicates: 0,
    }) + '\n');
    assert.equal(r.stderr, '');

    for (const args of [[badFile], [missing], [okFile, badFile], []]) {
      r = spawnSync(process.execPath, ['receipt-report.js', ...args], {
        cwd: new URL('..', import.meta.url).pathname,
        encoding: 'utf8',
      });
      assert.equal(r.status, 2, `args=${JSON.stringify(args)} stderr=${r.stderr}`);
      assert.equal(r.stdout, '', `args=${JSON.stringify(args)}`);
      assert.ok(r.stderr.length > 0, `args=${JSON.stringify(args)}: stderr empty`);
    }

    // CRLF file works end to end
    const crlfFile = join(dir, 'crlf.jsonl');
    writeFileSync(crlfFile, jsonl([start('s', 'x', 1, 0)]).split('\n').join('\r\n'), 'utf8');
    r = spawnSync(process.execPath, ['receipt-report.js', crlfFile], {
      cwd: new URL('..', import.meta.url).pathname,
      encoding: 'utf8',
    });
    assert.equal(r.status, 0, r.stderr);
    assert.deepEqual(JSON.parse(r.stdout), {
      jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] }],
      duplicates: 0,
    });
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

